// distant fog bands
if(S.district===0){ctx.fillStyle='#d3ddd52a';ctx.fillRect(0,110,1400,48);ctx.fillRect(0,680,1400,66)}
// landmarks
let d2=districts[S.district];sitesPos.forEach((p,i)=>{let [icon,label,type]=d2.sites[i],x=p[0],y=p[1];ctx.fillStyle='#14201ee8';ctx.beginPath();ctx.roundRect(x-48,y-25,96,55,10);ctx.fill();ctx.strokeStyle='#d5e7db55';ctx.lineWidth=1;ctx.stroke();ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText(icon,x,y-1);ctx.font='10px sans-serif';ctx.fillStyle='#e2ede6';ctx.fillText(label,x,y+18);if(i===near){ctx.strokeStyle='#9ae6bd';ctx.lineWidth=2;ctx.strokeRect(x-51,y-28,102,61)}});
// ambient walkers
