const sleep = ms => new Promise(r => setTimeout(r, ms));
const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = targets.find(t => t.type === 'page');
if (!page) throw new Error('No Chromium page target');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = e => {
  const msg = JSON.parse(e.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  else events.push(msg);
};
function call(method, params = {}) {
  const n = ++id;
  return new Promise((resolve, reject) => {
    pending.set(n, msg => msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result));
    ws.send(JSON.stringify({id:n, method, params}));
  });
}
async function evalJS(expression) {
  const result = await call('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true, userGesture:true});
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.text + ' :: ' + (result.exceptionDetails.exception?.description || ''));
  return result.result.value;
}
await call('Runtime.enable');
await call('Page.enable');
await sleep(800);
const report = {};
report.initial = await evalJS(`({title:document.title, clock:document.querySelector('#clock').textContent, canvas:!!document.querySelector('#world').getContext('2d'), needs:document.querySelectorAll('.need').length, district:document.querySelector('#districtName').textContent, saved:localStorage.getItem('baybound-save')})`);
await evalJS(`S.x=agents[1].x;S.y=agents[1].y;updateNear();interact()`);
report.npcDialog = await evalJS(`({open:document.querySelector('#dialog').classList.contains('open'), name:document.querySelector('#modalTitle').textContent})`);
await evalJS(`document.querySelector('.choice').click()`);
report.npcMemory = await evalJS(`({known:agents[1].known, trust:agents[1].trust, memory:agents[1].mem[0], log:S.log[0]})`);
await evalJS(`S.x=890;S.y=645;updateNear();interact()`);
report.hubDialog = await evalJS(`({title:document.querySelector('#modalTitle').textContent, choices:document.querySelectorAll('.choice').length})`);
await evalJS(`document.querySelector('.choice').click()`);
report.missionAccepted = await evalJS(`({mission:S.mission, objective:document.querySelector('#objective').innerText, modal:document.querySelector('#dialog').classList.contains('open')})`);
await evalJS(`S.x=385;S.y=620;updateNear();interact()`);
report.parkDialog = await evalJS(`({title:document.querySelector('#modalTitle').textContent, delivery:[...document.querySelectorAll('.choice b')].some(x=>x.textContent.includes('Deliver pantry'))})`);
const cashBefore = await evalJS('S.cash');
await evalJS(`([...document.querySelectorAll('.choice')].find(x=>x.innerText.includes('Deliver pantry')).click())`);
report.missionDone = await evalJS(`({status:S.mission.status, cash:S.cash, cashBefore:${cashBefore}, rep:S.rep, log:S.log[0]})`);
await evalJS(`openPhone()`);
report.phone = await evalJS(`({open:document.querySelector('#phone').classList.contains('open'), apps:document.querySelectorAll('.app').length})`);
await evalJS(`closePhone();toggleMap()`);
report.map = await evalJS(`({open:document.querySelector('#mapmodal').classList.contains('open'), districts:document.querySelectorAll('.maptile').length})`);
await evalJS(`toggleMap();window.dispatchEvent(new KeyboardEvent('keydown',{key:'d'}));`);
await sleep(120);
await evalJS(`window.dispatchEvent(new KeyboardEvent('keyup',{key:'d'}))`);
report.movement = await evalJS(`({x:S.x,y:S.y,clock:document.querySelector('#clock').textContent})`);
await evalJS(`save()`);
await call('Page.reload', {ignoreCache:true});
await sleep(1000);
report.restore = await evalJS(`({cash:S.cash,mission:S.mission?.status,agentKnown:agents[1].known,agentTrust:agents[1].trust,log:S.log[0]})`);
await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
report.mobile = await evalJS(`({viewport:innerWidth,side:getComputedStyle(document.querySelector('.left')).display,touch:getComputedStyle(document.querySelector('.touch')).display,scene:document.querySelector('.scene').getBoundingClientRect().width})`);
await call('Emulation.clearDeviceMetricsOverride');
report.exceptions = events.filter(e=>e.method==='Runtime.exceptionThrown').map(e=>e.params.exceptionDetails.text);
report.consoleErrors = events.filter(e=>e.method==='Runtime.consoleAPICalled'&&e.params.type==='error').map(e=>e.params.args.map(a=>a.value||a.description).join(' '));
console.log(JSON.stringify(report,null,2));
ws.close();

